// mobile-bff/routes/home.js
const express = require('express');
const router = express.Router();

const profileService = require('../clients/profileService');
const ordersService = require('../clients/ordersService');
const recommendationService = require('../clients/recommendationService');

router.get('/home', async (req, res) => {
  const userId = req.user.id;

  const [profileResult, ordersResult, recsResult] = await Promise.allSettled([
    profileService.getProfile(userId),
    ordersService.getRecentOrders(userId, { limit: 3 }),
    recommendationService.getRecommendations(userId, { limit: 5 }),
  ]);

  const profile = profileResult.status === 'fulfilled' ? profileResult.value : null;
  const orders = ordersResult.status === 'fulfilled' ? ordersResult.value : [];
  const recommendations = recsResult.status === 'fulfilled' ? recsResult.value : [];

  res.json({
    user: profile ? { name: profile.name, avatar: profile.avatarUrl } : null,
    recentOrders: orders.map(o => ({ id: o.id, status: o.status, total: o.total })),
    recommendations: recommendations.map(r => ({ id: r.id, title: r.title, price: r.price })),
  });
});

module.exports = router;

